function resetGame(){hudTickCounter=0;enemies=[];projectiles=[];gems=[];particles=[];visuals=[];fields=[];delayed=[];hazards=[];chests=[];GamePerf.reset();elapsed=0;spawnTimer=0;bossSpawned=false;boss=null;screenShake=0;flash=0;miniBossCount=0;nextMiniBossAt=60;const diff=difficultyDefs[selectedDifficulty];runDuration=diff.duration;finalBossAt=diff.bossAt;Object.assign(player,{x:0,y:0,facing:-Math.PI/2,moving:false,hp:100,maxHp:100,speed:170,level:1,xp:0,xpNeed:xpRequirement(1),kills:0,pickup:78,damageMul:1,eliteDamageMul:1,damageReduction:0,attackSpeedMul:1,xpMul:1,cooldownRate:1,killHeal:0,regen:0,regenTimer:8,invuln:0,fireTimer:.2,projectileBonus:0,pierceBonus:0,areaMul:1,critChance:.03,critDamage:1.5,projectileSpeedMul:1,poisonMul:1,dodgeCooldown:0,dodgeCooldownMul:1,dodgeDistanceMul:1,dodgeTimer:0,dodgeDuration:.18,dodgeInvuln:.2,dodgeVx:0,dodgeVy:0,saberUnityTimer:0,saberUnityTrue:false,cloudStep:0,lingbo:0,shrinkStep:0,speedBuff:0,arts:{},universal:Object.fromEntries(universal.map(u=>[u.id,0])),augments:{},chestsOpened:0,midBossKills:0,cooldowns:{meteor:0,tenk:0,dragonspin:0,starfall:0,overlord:0,arrowrain:0,sunmoon:0,thousand:0,miasma:0,lifedeath:0,firedragon:0,icepulse:0,fivethunder:0,whirlwind:0,mountain:0,demon:0,moonchain:0,zanshinDrop:0,nameless:0,hundredstep:0,taijifist:0,dragonreturn:0},hiddenReady:{},hiddenNotified:{},runGold:0,runOres:{},runSoulStones:0,forgedWeapon:null,huanglongStacks:0,tenThousandStacks:0,oneStrikeStacks:0,metrics:{kills:0,rangedKills:0,closeKills:0,poisonKills:0,elementalKills:0,pierceHits:0,brutes:0,elites:0,damageTaken:0,lowHpTime:0,noHit:0,maxNoHit:0,knockbacks:0,dodges:0}});const w=weaponDefs[selectedWeapon];player.arts[w.basic.id]=1;for(const a of w.arts)player.arts[a.id]=0;applyForgedWeapon();ui.weaponHud.textContent=`${w.name} · ${diff.name}${player.forgedWeapon?" · "+player.forgedWeapon.name:""}`;ui.bossWrap.style.display="none";updateHud()}

function startGame(){if(!selectedWeapon||difficultyDefs[selectedDifficulty].locked)return;initAudio();resetGame();updateCombatPortrait();state="playing";[ui.menu,ui.result,ui.pause,ui.levelUp,ui.augment,ui.forge].forEach(x=>x.classList.remove("show"));ui.dodgeBtn.style.display="flex";showMessage(`${difficultyDefs[selectedDifficulty].name} · ${weaponDefs[selectedWeapon].name}의 길이 시작되었다`,2);last=performance.now()}
function endGame(win,reason=""){state=win?"victory":"gameover";pointer.active=false;ui.joystick.style.display="none";ui.dodgeBtn.style.display="none";if(win){const d=difficultyDefs[selectedDifficulty],clear=Math.floor(d.clearGold??80*d.rank);account.gold+=clear;player.runGold+=clear}saveRecords();ui.resultTitle.textContent=win?"천하에 이름을 떨쳤다":reason==="time"?"혈겁에 삼켜졌다":"주화입마";const w=weaponDefs[selectedWeapon],d=difficultyDefs[selectedDifficulty],hiddenCount=w.arts.filter(a=>a.hidden&&(player.arts[a.id]||0)>0).length,oreCount=Object.values(player.runOres).reduce((a,b)=>a+b,0);ui.finalStats.innerHTML=`난이도 <b>${d.name}</b> · 무기군 <b>${w.name}</b><br>생존 <b>${fmtTime(elapsed)}</b> · 격파 <b>${player.kills}명</b><br>중간 보스 <b>${player.midBossKills}명</b> · 도달 경지 <b>${player.level}</b><br>획득 <b>금자 ${Math.floor(player.runGold)}</b> · 광석 <b>${oreCount}개</b> · 무혼석 <b>${player.runSoulStones||0}개</b><br>히든 무공 <b>${hiddenCount}개 습득</b>${player.forgedWeapon?`<br>장착 무기 <b>${player.forgedWeapon.name}</b>${window.CombatPowerSystem?` · 전투력 <b>${CombatPowerSystem.format(CombatPowerSystem.value(player.forgedWeapon))}</b>`:""}`:""}${reason==="time"?'<br><span class="danger-note">제한시간 안에 혈마를 처치하지 못했다.</span>':""}`;ui.result.classList.add("show");GameAudio.playUI(win?"victory":"defeat")}

function pauseGame(){if(state!=="playing")return;state="paused";ui.dodgeBtn.style.display="none";renderPause();ui.pause.classList.add("show")}
function resumeGame(){if(state!=="paused")return;state="playing";ui.pause.classList.remove("show");ui.dodgeBtn.style.display="flex";last=performance.now()}
function renderPause(){const w=weaponDefs[selectedWeapon],d=difficultyDefs[selectedDifficulty];ui.pauseWeapon.textContent=`${w.icon} ${w.name} · ${d.name}`;ui.pauseRun.textContent=d.endless?`생존 ${fmtTime(elapsed)} · 격파 ${player.kills}`:`남은 ${fmtTime(runDuration-elapsed)} · 격파 ${player.kills}`;const stat=[["체력",`${Math.ceil(player.hp)}/${player.maxHp}`],["피해 배율",`${player.damageMul.toFixed(2)}x`],["피해 감소",`${Math.round(player.damageReduction*100)}%`],["투사체",`+${player.projectileBonus}`],["관통",`+${player.pierceBonus}`],["치명타",`${Math.round(player.critChance*100)}%`],["범위",`${player.areaMul.toFixed(2)}x`],["회피 쿨",`${Math.max(1.05,4.2*player.dodgeCooldownMul).toFixed(1)}초`],["경지",player.level]];const arts=[w.basic,...w.arts];const augmentRows=augmentDefs.filter(a=>(player.augments[a.id]||0)>0).map(a=>`<div class="augment-row"><strong><span>${a.name}</span><span>${player.augments[a.id]}중</span></strong><p>${a.desc}</p></div>`).join("")||'<p class="desc">아직 획득한 증강이 없다.</p>';const passiveRows=universal.filter(a=>(player.universal[a.id]||0)>0).map(a=>`<div class="augment-row"><strong><span>${a.name}</span><span>${player.universal[a.id]}성</span></strong><p>${a.desc}</p></div>`).join("")||'<p class="desc">아직 공통 심법을 익히지 않았다.</p>';ui.pauseContent.innerHTML=`<h3>전투 상황</h3><div class="stat-grid"><div class="stat"><b>${d.name}</b><span>난이도</span></div><div class="stat"><b>${d.endless?fmtTime(elapsed):fmtTime(runDuration-elapsed)}</b><span>${d.endless?"생존 시간":"남은 시간"}</span></div><div class="stat"><b>${player.midBossKills}</b><span>중간 보스</span></div></div><h3>현재 능력</h3><div class="stat-grid">${stat.map(s=>`<div class="stat"><b>${s[1]}</b><span>${s[0]}</span></div>`).join("")}</div>${player.forgedWeapon?`<h3>장착 무기</h3><div class="art-row"><strong><span>${player.forgedWeapon.name}</span><span>${window.CombatPowerSystem?"전투력 "+CombatPowerSystem.format(CombatPowerSystem.value(player.forgedWeapon)):player.forgedWeapon.damageMul.toFixed(2)+"x"}</span></strong><p>${player.forgedWeapon.abilityName} · ${player.forgedWeapon.abilityDesc}</p>${player.forgeMilestones?.length?`<p>${player.forgeMilestones.join("<br>")}</p>`:""}${player.potentialResonance?`<p>✦ ${player.potentialResonance}</p>`:""}</div>`:""}<h3>습득 무공</h3><div class="art-list">${arts.map(a=>{const lv=player.arts[a.id]||0,prog=a.hidden?a.progress(player):null;return`<div class="art-row ${lv?"":"locked"}"><strong><span>${a.hidden?"✦ ":""}${a.name}</span><span>${lv?lv+"성":"미습득"}</span></strong><p>${a.desc}</p>${a.hidden&&!lv?`<p>조건: ${a.condition}<br>${prog.text}</p><div class="progress"><span style="width:${prog.v*100}%"></span></div>`:""}</div>`}).join("")}</div><h3>공통 심법·보법</h3><div class="art-list">${passiveRows}</div><h3>증강</h3><div class="art-list">${augmentRows}</div><h3>이번 원정 전리품</h3><div class="stat-grid"><div class="stat"><b>${Math.floor(player.runGold)}</b><span>금자</span></div><div class="stat"><b>${Object.values(player.runOres).reduce((a,b)=>a+b,0)}</b><span>광석</span></div><div class="stat"><b>${player.metrics.dodges}</b><span>회피</span></div></div>`}


function checkHidden(){for(const h of weaponDefs[selectedWeapon].arts.filter(a=>a.hidden)){if(!player.hiddenReady[h.id]&&h.ready(player)){player.hiddenReady[h.id]=true;if(!player.hiddenNotified[h.id]){player.hiddenNotified[h.id]=true;showMessage(`히든 무공의 단서 완성: ${h.name}`,3);GameAudio.playUI("hidden-ready")}}}}
function choicePool(){const w=weaponDefs[selectedWeapon],pool=[];const arts=[w.basic,...w.arts];for(const a of arts){const lv=player.arts[a.id]||0;if(a.hidden&&!player.hiddenReady[a.id]&&lv===0)continue;if(lv<a.max){pool.push({kind:"art",id:a.id,name:a.name,tag:a.hidden?"히든 무공":lv?"무공 강화":"무공 습득",desc:lv?`${lv+1}성: ${a.desc}`:`새 무공 해금: ${a.desc}`,apply:()=>{player.arts[a.id]=lv+1;if(a.onLearn)a.onLearn(player,lv+1)}})}}for(const u of universal){const lv=player.universal[u.id]||0;if(lv<u.max)pool.push({kind:"universal",id:u.id,name:u.name,tag:u.tag||"내공·신법",desc:`${lv+1}성: ${u.desc}`,apply:()=>{player.universal[u.id]=lv+1;u.apply(player)}})}return pool}
function levelChoice(){
  state="levelup";
  ui.dodgeBtn.style.display="none";

  const pool=choicePool();
  const artPool=pool.filter(x=>x.kind==="art");
  const pick=[];

  /** 중복 없이 무작위 선택지를 하나 뽑는다. */
  function take(src){
    if(!src.length)return;
    const i=Math.floor(Math.random()*src.length);
    const choice=src.splice(i,1)[0];
    const j=pool.indexOf(choice);
    if(j>=0)pool.splice(j,1);
    pick.push(choice);
  }

  take(artPool);
  take(artPool);
  while(pick.length<3&&pool.length)take(pool);

  // 모든 유한 성장 요소를 완성한 뒤에도 게임이 멈추지 않도록 반복 보상을 제공한다.
  const repeatChoices=[
    {kind:"repeat",name:"내공 정련",tag:"반복 성장",desc:"모든 피해가 영구적으로 2% 증가한다.",apply:()=>{player.damageMul*=1.02}},
    {kind:"repeat",name:"기혈 순환",tag:"반복 성장",desc:"최대 체력이 5 증가하고 최대 체력의 20%를 회복한다.",apply:()=>{player.maxHp+=5;player.hp=Math.min(player.maxHp,player.hp+player.maxHp*.2)}},
    {kind:"repeat",name:"신법 연마",tag:"반복 성장",desc:"이동속도가 1.5% 증가하고 보법 재사용 대기시간이 1% 감소한다.",apply:()=>{player.speed*=1.015;player.dodgeCooldownMul=Math.max(.55,player.dodgeCooldownMul*.99)}}
  ];
  for(const reward of repeatChoices){
    if(pick.length>=3)break;
    pick.push(reward);
  }

  const ready=weaponDefs[selectedWeapon].arts.filter(a=>a.hidden&&player.hiddenReady[a.id]&&!player.arts[a.id]);
  ui.hiddenBanner.innerHTML=ready.length?`<div class="unlock-banner">히든 단서 완성: ${ready.map(a=>a.name).join(" · ")}</div><div style="height:9px"></div>`:"";
  ui.choices.innerHTML="";

  pick.forEach(choice=>{
    const button=document.createElement("button");
    button.type="button";
    button.className="choice";
    button.innerHTML=`<strong>${choice.name}<span class="tag">${choice.tag}</span></strong><small>${choice.desc}</small>`;
    button.addEventListener("click",()=>{
      choice.apply();
      ui.levelUp.classList.remove("show");
      state="playing";
      ui.dodgeBtn.style.display="flex";
      GameAudio.playUI("level-choice");
      showMessage(`${choice.name}의 깨달음을 얻었다`,1.5);
      last=performance.now();
    },{once:true});
    ui.choices.appendChild(button);
  });
  ui.levelUp.classList.add("show");
}
function openAugmentChoice(){state="augment";ui.dodgeBtn.style.display="none";const pool=augmentDefs.filter(a=>(player.augments[a.id]||0)<a.max),pick=[];while(pool.length&&pick.length<3)pick.push(pool.splice(Math.floor(Math.random()*pool.length),1)[0]);if(!pick.length){player.hp=player.maxHp;state="playing";ui.dodgeBtn.style.display="flex";showMessage("모든 증강을 완성해 기혈이 회복되었다",1.5);return}ui.augmentChoices.innerHTML="";pick.forEach(a=>{const lv=player.augments[a.id]||0,b=document.createElement("button");b.type="button";b.className="choice";b.innerHTML=`<strong>${a.name}<span class="tag">증강 ${lv+1}/${a.max}</span></strong><small>${a.desc}</small>`;b.addEventListener("click",()=>{player.augments[a.id]=lv+1;a.apply(player);ui.augment.classList.remove("show");state="playing";ui.dodgeBtn.style.display="flex";showMessage(`${a.name} 증강을 획득했다`,1.5);GameAudio.playUI("augment-take");last=performance.now()},{once:true});ui.augmentChoices.appendChild(b)});ui.augment.classList.add("show");GameAudio.playUI("augment-open")}
function gainXp(n){player.xp+=n*player.xpMul;let up=false;while(player.xp>=player.xpNeed){player.xp-=player.xpNeed;player.level++;player.xpNeed=xpRequirement(player.level);up=true}if(up)levelChoice()}

function enemyDef(type){
  const difficulty=difficultyDefs[selectedDifficulty],base=GameBalance.enemyArchetypes[type]||GameBalance.enemyArchetypes.bandit;
  const scale=(1+elapsed/difficulty.scaleTime)*difficulty.enemyHp;
  return {r:base.r,hp:base.hp*scale,speed:(base.speed+elapsed*base.speedGrowth)*difficulty.enemySpeed,damage:base.damage*difficulty.enemyDamage,xp:base.xp,color:base.color};
}

function spawnEnemy(type,x,y){const d=enemyDef(type);enemies.push({type,x,y,r:d.r,hp:d.hp,maxHp:d.hp,speed:d.speed,damage:d.damage,xp:d.xp,color:d.color,hit:0,orbitHit:0,pushX:0,pushY:0,slow:1,slowTime:0,stunTime:0,poison:0,poisonTime:0,poisonTick:0,dead:false})}
function spawnAround(type,dist=0){const a=Math.random()*Math.PI*2,r=dist||Math.max(W,H)*.63+90+Math.random()*140;spawnEnemy(type,player.x+Math.cos(a)*r,player.y+Math.sin(a)*r)}
function spawnMiniBoss(){miniBossCount++;const d=difficultyDefs[selectedDifficulty],a=Math.random()*Math.PI*2,r=Math.max(W,H)*.63+150,types=[{subtype:"blackblade",name:"흑도객",color:"#653d37",speed:60,r:26},{subtype:"poisonhand",name:"독수귀",color:"#665078",speed:52,r:25},{subtype:"ironmonk",name:"철탑승",color:"#71624d",speed:43,r:30}],t=types[(miniBossCount-1)%types.length],hp=d.miniHp+d.miniGrowth*miniBossCount+player.level*32,e={type:"midboss",subtype:t.subtype,bossName:t.name,x:player.x+Math.cos(a)*r,y:player.y+Math.sin(a)*r,r:t.r,hp,maxHp:hp,speed:t.speed*d.enemySpeed,damage:d.miniDamage+miniBossCount*1.5,xp:0,color:t.color,hit:0,orbitHit:0,pushX:0,pushY:0,slow:1,slowTime:0,stunTime:0,poison:0,poisonTime:0,poisonTick:0,dead:false,special:2.3,chargeDelay:0,chargeTime:0,chargeVx:0,chargeVy:0};enemies.push(e);showMessage(`${miniBossCount}분 중간 보스 · ${t.name} 출현`,2.2);GameAudio.playSFX("midboss-spawn")}
function spawnBoss(){bossSpawned=true;const d=difficultyDefs[selectedDifficulty],a=Math.random()*Math.PI*2,r=Math.max(W,H)*.65+160,hp=d.bossHp+player.level*d.bossLevelHp;boss={type:"boss",bossName:"혈마",x:player.x+Math.cos(a)*r,y:player.y+Math.sin(a)*r,r:43,hp,maxHp:hp,speed:d.bossSpeed,damage:d.bossDamage,xp:0,color:"#8b2929",hit:0,orbitHit:0,pushX:0,pushY:0,slow:1,slowTime:0,stunTime:0,poison:0,poisonTime:0,poisonTick:0,dead:false,summon:d.summon,blast:d.blast,dash:d.dash,orbs:d.orbs,phase2:false,chargeDelay:0,chargeTime:0,chargeVx:0,chargeVy:0};enemies.push(boss);ui.bossWrap.style.display="block";showMessage(d.endless?`${d.name} · 혈마가 나락에서 솟아올랐다`:`${d.name}의 혈마가 강림했다 · 1분 안에 처치하라`,3);GameAudio.playSFX("boss-spawn")}
function nearest(max=820,fromX=player.x,fromY=player.y,exclude=[]){let b=null,bd=max*max;for(const e of GameSpatial.queryCircle(fromX,fromY,max)){if(e.dead||exclude.includes(e))continue;const dx=e.x-fromX,dy=e.y-fromY,d=dx*dx+dy*dy;if(d<bd){bd=d;b=e}}return b}
function addVisual(v){const item=Object.assign({life:.3,max:.3,color:C[selectedWeapon]},v);item.life=Number.isFinite(item.life)?Math.max(0,Math.min(item.life,GAME_OBJECT_LIMITS.visualMaxLife)):0;item.max=Number.isFinite(item.max)?Math.max(item.life,Math.min(item.max,GAME_OBJECT_LIMITS.visualMaxLife)):item.life;item.age=0;if(item.belowType){let idx=-1;for(let i=visuals.length-1;i>=0;i--){if(visuals[i].type===item.belowType&&visuals[i].life>0){idx=i;break}}if(idx>=0){visuals.splice(idx,0,item);return item}}visuals.push(item);return item}
function particle(x,y,color=C[selectedWeapon],speed=80,n=1){const q=account.settings?.quality||"normal",baseLimit=q==="low"?GameBalance.limits.maxParticlesLow:q==="high"?GameBalance.limits.maxParticlesHigh:GameBalance.limits.maxParticlesNormal,gameSpeed=Math.max(1,Number(account.settings?.gameSpeed||1)),speedScale=gameSpeed>=3?.62:gameSpeed>=2?.76:gameSpeed>=1.5?.9:1,limit=Math.max(100,Math.floor(baseLimit*speedScale));for(let i=0;i<n&&particles.length<limit;i++){const a=Math.random()*Math.PI*2,s=Math.random()*speed;particles.push(GamePools.particle.acquire({x:0,y:0,vx:0,vy:0,life:0,max:.6,color:"#fff"},{x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.25+Math.random()*.35,max:.6,color}))}}
function projectile(o){const p=GamePools.projectile.acquire({x:player.x,y:player.y,vx:0,vy:0,r:4,life:1.5,damage:15,pierce:0,hits:0,shape:"blade",color:C[selectedWeapon],source:"basic",homing:0,poison:0,poisonTime:0,explode:0,knock:0,elemental:false,trail:0,ignorePassive:false,curve:0,deathPoisonTime:0,disarm:0},o);if(!p.ignorePassive){p.pierce+=player.pierceBonus;p.vx*=player.projectileSpeedMul;p.vy*=player.projectileSpeedMul;p.poison*=player.poisonMul}projectiles.push(p)}
function facingAngle(){return Number.isFinite(player.facing)?player.facing:-Math.PI/2}
function visibleEnemies(margin=42){const z=Math.max(.01,typeof mobileCameraScale==="function"?mobileCameraScale():1),halfW=W/(2*z),halfH=H/(2*z),l=player.x-halfW+margin,r=player.x+halfW-margin,t=player.y-halfH+margin,b=player.y+halfH-margin;return enemies.filter(e=>!e.dead&&e.x>l&&e.x<r&&e.y>t&&e.y<b)}
function densestForwardDirection(length,halfWidth){const candidates=visibleEnemies(-24).slice(0,96);if(!candidates.length)return Number.isFinite(player.facing)?player.facing:-Math.PI/2;let bestAngle=Math.atan2(candidates[0].y-player.y,candidates[0].x-player.x),bestScore=-Infinity;const angles=[];for(const e of candidates)angles.push(Math.atan2(e.y-player.y,e.x-player.x));for(let i=0;i<16;i++)angles.push(-Math.PI+i*Math.PI/8);for(const a of angles){const ca=Math.cos(a),sa=Math.sin(a);let count=0,score=0;for(const e of candidates){const dx=e.x-player.x,dy=e.y-player.y,along=dx*ca+dy*sa;if(along<-e.r||along>length+e.r)continue;const side=Math.abs(-dx*sa+dy*ca);if(side>halfWidth+e.r)continue;count++;score+=1+Math.max(0,1-along/Math.max(1,length))*.18}score+=count*4;if(score>bestScore){bestScore=score;bestAngle=a}}return bestAngle}
function taijiCount(lv){return Math.min(8,1+lv+Math.floor(lv/3))}
function taijiRadius(lv){return 50+lv*11}
function taijiBladeSize(lv){return 9+lv*1.8}
function katanaSlashCount(lv){return Math.min(5,1+Math.floor(lv/2))}
function aoe(x,y,r,damage,source,opt={}){r*=player.areaMul;if(!opt.skipVisual)addVisual({type:"ring",x,y,r,life:.32,max:.32,color:opt.color||C[selectedWeapon],width:opt.width||5,source:opt.vfxSource||source});for(const e of GameSpatial.queryCircle(x,y,r+64)){if(e.dead)continue;const d=Math.hypot(e.x-x,e.y-y);if(d<r+e.r){damageEnemy(e,damage,source,Object.assign({},opt,{distance:d}));if(opt.knock){const n=d||1;e.pushX+=(e.x-x)/n*opt.knock;e.pushY+=(e.y-y)/n*opt.knock;player.metrics.knockbacks++}}}}
