function performDodge(){if(state!=="playing"||player.dodgeCooldown>0||player.dodgeTimer>0)return;initAudio();const a=facingAngle(),distance=(115+player.shrinkStep*12)*player.dodgeDistanceMul,duration=Math.max(.14,player.dodgeDuration),sx=player.x,sy=player.y;player.dodgeTimer=duration;player.dodgeVx=Math.cos(a)*distance/duration;player.dodgeVy=Math.sin(a)*distance/duration;player.dodgeCooldown=Math.max(1.05,4.2*player.dodgeCooldownMul);player.invuln=Math.max(player.invuln,duration+player.dodgeInvuln);player.metrics.dodges++;if(player.cloudStep)player.speedBuff=1.4+.25*player.cloudStep;if(player.lingbo)aoe(sx,sy,34+player.lingbo*12,10+player.lingbo*9,"footwork",{color:"#b9e6df",knock:80});if(player.shrinkStep)lineHit(sx,sy,sx+Math.cos(a)*distance,sy+Math.sin(a)*distance,8+player.shrinkStep*3,9+player.shrinkStep*8,"footwork",{color:"#d8f5ff",life:.24});addVisual({type:"afterimage",x:sx,y:sy,r:18+player.lingbo*3,life:.36,max:.36,color:"#b9e6df"});addVisual({type:"line",x1:sx,y1:sy,x2:sx+Math.cos(a)*distance,y2:sy+Math.sin(a)*distance,width:5,life:.2,max:.2,color:"#d8f5ff"});GameAudio.playSFX("dodge")}
function updateInput(){
  const settings=account.settings||{};
  let x=0,y=0;
  if(keys[settings.keyMoveLeft||"KeyA"]||keys.ArrowLeft)x--;
  if(keys[settings.keyMoveRight||"KeyD"]||keys.ArrowRight)x++;
  if(keys[settings.keyMoveUp||"KeyW"]||keys.ArrowUp)y--;
  if(keys[settings.keyMoveDown||"KeyS"]||keys.ArrowDown)y++;
  if(pointer.active){
    const dx=pointer.x-pointer.ox,dy=pointer.y-pointer.oy,l=Math.hypot(dx,dy),max=44*(settings.joystickSize||1),m=Math.min(max,l),nx=l?dx/l:0,ny=l?dy/l:0;
    x=nx*m/max;y=ny*m/max;
    ui.stick.style.transform=`translate(calc(-50% + ${nx*m}px),calc(-50% + ${ny*m}px))`;
  }
  const l=Math.hypot(x,y);if(l>1){x/=l;y/=l}move.x=x;move.y=y;
}

/** 배열을 새로 만들지 않고 활성 객체만 앞쪽으로 압축한다. 후반 GC 스파이크를 줄이기 위한 hot-path 유틸리티다. */
function compactActive(list,isActive,onRemove=null){let write=0;for(let read=0;read<list.length;read++){const item=list[read];if(isActive(item)){list[write++]=item}else if(onRemove)onRemove(item)}list.length=write;return list}

function updateCombatPortrait(){
  const wrap=document.getElementById("combatPortraitWrap");
  if(!selectedWeapon||!characterDefs[selectedWeapon]){if(wrap)wrap.style.display="none";return;}
  const ch=characterDefs[selectedWeapon];
  if(wrap){wrap.style.display="block";wrap.dataset.weapon=selectedWeapon;}
  if(ui.combatPortrait){
    const raw=`assets/portraits/${selectedWeapon}.png`;
    ui.combatPortrait.alt=`${ch.name} 초상화`;
    ui.combatPortrait.classList.remove("portrait-error");
    ui.combatPortrait.onerror=()=>{
      ui.combatPortrait.onerror=null;
      ui.combatPortrait.classList.add("portrait-error");
      // PWA/URL 캐시 파라미터 경로가 실패하는 환경에서는 순수 상대경로로 한 번 더 시도한다.
      if(!ui.combatPortrait.src.endsWith(raw))ui.combatPortrait.src=raw;
    };
    ui.combatPortrait.src=(typeof GameAssets!=="undefined"&&GameAssets.url)?GameAssets.url(raw):raw;
  }
  if(ui.combatPortraitName)ui.combatPortraitName.textContent=ch.name;
}
