 if(d.rank>=2&&e.puddle<=0){e.puddle=e.phase3?3.4:5.7;const count=e.phase3?3:2;for(let i=0;i<count;i++){const ang=Math.random()*Math.PI*2,dist=60+Math.random()*120;hazards.push({type:"puddle",x:player.x+Math.cos(ang)*dist,y:player.y+Math.sin(ang)*dist,r:e.phase3?62:50,life:e.phase3?5.2:4.2,damage:e.damage*.45,tick:.3,color:e.phase3?"rgba(136,27,36,.58)":"rgba(110,20,30,.52)",dead:false})}showMessage("혈마 · 혈지장",.8)}
