function prepareCharge(e,speed,damage){const a=Math.atan2(player.y-e.y,player.x-e.x);e.chargeDelay=.44;e.chargeTime=.62;e.chargeVx=Math.cos(a)*speed;e.chargeVy=Math.sin(a)*speed;e.chargeDamage=damage||e.damage;addVisual({type:"line",x1:e.x,y1:e.y,x2:e.x+Math.cos(a)*500,y2:e.y+Math.sin(a)*500,width:4,life:.44,max:.44,color:"#d35a5a"})}
function updateProjectiles(dt){
 for(const p of projectiles){
  if(p.ricochetUltimate){
   const z=Math.max(.01,mobileCameraScale()),halfW=W/(2*z),halfH=H/(2*z),margin=(p.r||4)+5;
   const left=player.x-halfW+margin,right=player.x+halfW-margin,top=player.y-halfH+margin,bottom=player.y+halfH-margin;
   p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;
   for(let guard=0;guard<4&&(p.x<left||p.x>right);guard++){if(p.x<left){p.x=left+(left-p.x);p.vx=Math.abs(p.vx)}else if(p.x>right){p.x=right-(p.x-right);p.vx=-Math.abs(p.vx)}}
   for(let guard=0;guard<4&&(p.y<top||p.y>bottom);guard++){if(p.y<top){p.y=top+(top-p.y);p.vy=Math.abs(p.vy)}else if(p.y>bottom){p.y=bottom-(p.y-bottom);p.vy=-Math.abs(p.vy)}}
   if(p.trail&&Math.random()<.78)particle(p.x,p.y,p.color,28,1);
   const registry=p.hitRegistry||(p.hitRegistry=new Map()),now=elapsed;
   for(const e of GameSpatial.queryCircle(p.x,p.y,p.r+72)){
    if(e.dead)continue;
    const rr=e.r+p.r;if((e.x-p.x)**2+(e.y-p.y)**2>=rr*rr)continue;
    const next=registry.get(e)||0;if(now<next)continue;
    registry.set(e,now+(p.rehitDelay||.30));
    damageEnemy(e,p.damage,"ultimate",{color:p.color,shake:2.5,distance:Math.hypot(e.x-player.x,e.y-player.y)});
   }
   continue;
  }
  if(p.curve){const sp=Math.hypot(p.vx,p.vy),aa=Math.atan2(p.vy,p.vx)+p.curve*dt;p.vx=Math.cos(aa)*sp;p.vy=Math.sin(aa)*sp}
  if(p.homing){const t=p.targetEnemy&&!p.targetEnemy.dead?p.targetEnemy:nearest(360,p.x,p.y);if(t){const sp=Math.hypot(p.vx,p.vy),ta=Math.atan2(t.y-p.y,t.x-p.x),ca=Math.atan2(p.vy,p.vx),da=Math.atan2(Math.sin(ta-ca),Math.cos(ta-ca)),na=ca+da*Math.min(1,p.homing*dt);p.vx=Math.cos(na)*sp;p.vy=Math.sin(na)*sp}}
  p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;if(p.trail&&Math.random()<.55)particle(p.x,p.y,p.color,20,1);
  for(const e of GameSpatial.queryCircle(p.x,p.y,p.r+72)){if(e.dead||p.hits>p.pierce)break;const rr=e.r+p.r;if((e.x-p.x)**2+(e.y-p.y)**2<rr*rr){damageEnemy(e,p.damage,p.source,{poison:p.poison,poisonTime:p.poisonTime,deathPoisonTime:p.deathPoisonTime,disarm:p.disarm,knock:p.knock,elemental:p.elemental,color:p.color,slow:player.forgedWeapon&&player.forgedWeapon.ability==="ice"?.84:0,slowTime:1.3,distance:Math.hypot(e.x-player.x,e.y-player.y)});if(player.forgedWeapon&&player.forgedWeapon.ability==="fire"&&Math.random()<.08)aoe(p.x,p.y,34,Math.max(4,p.damage*.32),"forgefire",{color:"#ef8052",elemental:true,shake:2});if(player.forgedWeapon&&player.forgedWeapon.ability==="thunder"&&Math.random()<.08){const z=nearest(125,e.x,e.y,[e]);if(z){addVisual({type:"lightning",x1:e.x,y1:e.y,x2:z.x,y2:z.y,width:2,life:.13,max:.13,color:"#8bd5ff"});damageEnemy(z,p.damage*.28,"forgethunder",{elemental:true,color:"#8bd5ff"})}}if(p.shape==="spear"&&p.hits>0)player.metrics.pierceHits++;if(p.knock){const d=Math.hypot(e.x-p.x,e.y-p.y)||1;e.pushX+=(e.x-p.x)/d*p.knock;e.pushY+=(e.y-p.y)/d*p.knock;player.metrics.knockbacks++}if(p.source==="hundredstep"){addVisual({type:"skillFistHundredCombo",x:e.x,y:e.y,a:Math.atan2(e.y-player.y,e.x-player.x),r:92,life:1.0,max:1.0,color:"#f5cf6a",holdAlpha:true});aoe(e.x,e.y,62,p.damage*.42,"hundredstepCombo",{knock:115,color:"#f5cf6a",skipVisual:true,skipImpactVfx:true})}p.hits++;if(p.shape==="poisonButterfly"){addVisual({type:"skillExplodedButterfly",x:p.x,y:p.y,r:82,life:1.05,max:1.05,color:"#86b8ff",holdAlpha:true});aoe(p.x,p.y,72,34,"ultimate",{slow:.62,slowTime:4.5,disarm:4.2,color:"#8a7be8",shake:5,skipVisual:true,skipImpactVfx:true});p.hits=p.pierce+1;continue}if(p.explode){if(p.source==="skyflower"){addVisual({type:"skillStingrainExplosion",x:p.x,y:p.y,r:56+p.explode*.35,life:.63,max:.63,color:C.poison,holdAlpha:true});aoe(p.x,p.y,p.explode,p.damage*.72,"skyflower",{poison:p.poison,poisonTime:p.poisonTime,deathPoisonTime:p.deathPoisonTime,color:C.poison,shake:3,skipVisual:true,skipImpactVfx:true});p.hits=p.pierce+1}else if(p.source==="firedragon"){const burstR=Math.max(110,p.explode*1.38);addVisual({type:"skillTaoFireDragon",x:p.x,y:p.y,r:burstR,life:.62,max:.62,color:"#ff8c52",burst:true,visibilityBoost:1.12,holdAlpha:true});aoe(p.x,p.y,p.explode,p.damage*.78,"firedragon",{elemental:true,color:"#ff8c52",shake:7});const lv=Math.max(1,p.fireDragonLevel||1),chainCount=Math.min(3,Math.floor(lv/2));if(chainCount>0){const candidates=GameSpatial.queryCircle(p.x,p.y,300).filter(z=>!z.dead&&z!==e).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y)).slice(0,chainCount);candidates.forEach((z,i)=>delayed.push({time:.14*(i+1),type:"fireDragonChain",x:z.x,y:z.y,r:p.explode*(.82+i*.05),damage:p.damage*(.52-i*.05),color:"#ff985c",source:"firedragon"}))}}else aoe(p.x,p.y,p.explode,p.damage*.72,p.source,{elemental:p.elemental,color:p.color,shake:5});p.hits=p.pierce+1}}}
 }
}
function updateEnemies(dt){for(const e of enemies){if(e.dead)continue;e.hit=Math.max(0,e.hit-dt);e.orbitHit=Math.max(0,e.orbitHit-dt);e.deathPoisonTime=Math.max(0,(e.deathPoisonTime||0)-dt);e.disarmTime=Math.max(0,(e.disarmTime||0)-dt);if(e.poisonTime>0){e.poisonTime-=dt;e.poisonTick=(e.poisonTick||0)-dt;if(e.poisonTick<=0){e.poisonTick=.55;const stacks=Math.max(1,Math.min(POISON_STACK_CAP,e.poisonStacks||1));damageEnemy(e,(e.poison||0)*stacks*.28,"poison",{color:C.poison,skipImpactVfx:true})}if(e.poisonTime<=0){e.poison=0;e.poisonStacks=0}}if(e.slowTime>0)e.slowTime-=dt;else e.slow=1;if((e.stunTime||0)>0){e.stunTime=Math.max(0,e.stunTime-dt);e.pushX*=Math.pow(.025,dt);e.pushY*=Math.pow(.025,dt);continue}const dx=player.x-e.x,dy=player.y-e.y,d=Math.hypot(dx,dy)||1;if(e.chargeDelay>0){e.chargeDelay-=dt}else if(e.chargeTime>0){e.chargeTime-=dt;e.x+=e.chargeVx*dt;e.y+=e.chargeVy*dt}else{const sp=e.speed*e.slow*(e.type==="boss"&&d<130?.55:1);e.x+=(dx/d*sp+e.pushX)*dt;e.y+=(dy/d*sp+e.pushY)*dt}e.pushX*=Math.pow(.025,dt);e.pushY*=Math.pow(.025,dt);if(d<(player.hitRadius||player.r)+e.r&&player.invuln<=0)hurtPlayer(e.chargeTime>0?(e.chargeDamage||e.damage):e.damage)}}
let gemMaintenanceTimer=0;
function mergeXpGemsIfNeeded(){
 const live=[];for(const g of gems)if(!g.dead&&g.kind==="xp")live.push(g);
 if(live.length<=GAME_OBJECT_LIMITS.xpGemsSoft)return;
 const cells=new Map(),cellSize=96;let merged=0;
 for(const g of live){const key=`${Math.floor(g.x/cellSize)},${Math.floor(g.y/cellSize)}`,target=cells.get(key);if(!target){cells.set(key,g);continue}target.value=(target.value||0)+(g.value||0);target.r=Math.min(10,Math.max(target.r||5,g.r||5)+.12);g.dead=true;merged++}
 const survivors=[...cells.values()].filter(g=>!g.dead);
 if(survivors.length>GAME_OBJECT_LIMITS.xpGemsSoft){const keep=survivors.slice(0,GAME_OBJECT_LIMITS.xpGemsSoft);for(let i=GAME_OBJECT_LIMITS.xpGemsSoft;i<survivors.length;i++){const g=survivors[i],target=keep[i%keep.length];target.value=(target.value||0)+(g.value||0);g.dead=true;merged++}}
 if(merged)GamePerf.noteXpMerged(merged);
}
function updateGems(dt){gemMaintenanceTimer-=dt;if(gemMaintenanceTimer<=0){gemMaintenanceTimer=.5;mergeXpGemsIfNeeded()}for(const g of gems){const dx=player.x-g.x,dy=player.y-g.y,d=Math.hypot(dx,dy)||1;if(d<player.pickup*2.2){const pull=190+(player.pickup*2.2-d)*4;g.vx+=dx/d*pull*dt;g.vy+=dy/d*pull*dt}g.vx*=Math.pow(.12,dt);g.vy*=Math.pow(.12,dt);g.x+=g.vx*dt;g.y+=g.vy*dt;if(d<(player.hitRadius||player.r)+g.r+5){g.dead=true;if(g.kind==="heal"||g.heal){player.hp=Math.min(player.maxHp,player.hp+(g.heal||15));showMessage("영약을 복용했다",.9)}else if(g.kind==="gold"){account.gold+=g.value;player.runGold+=g.value}else if(g.kind==="ore"){const k=oreKey(g.type,g.grade);account.ores[k]=(account.ores[k]||0)+1;player.runOres[k]=(player.runOres[k]||0)+1;showMessage(`${gradeName(g.grade)} ${oreTypes[g.type].name} 획득`,1.1)}else if(g.kind==="soulstone"){account.weaponSoulStones=Math.max(0,Math.floor(Number(account.weaponSoulStones)||0))+1;player.runSoulStones=(player.runSoulStones||0)+1;showMessage("무혼석 획득 · 파괴 무기 복구 재료",1.3)}else gainXp(g.value);refreshAccountUI();GameAudio.playUI(g.kind==="ore"||g.kind==="soulstone"?"ore-pickup":g.kind==="gold"?"gold-pickup":g.kind==="heal"||g.heal?"heal-pickup":"pickup")}}}

function updateChests(dt){if(state!=="playing")return;for(const c of chests){c.bob+=dt*3;const d=Math.hypot(player.x-c.x,player.y-c.y);if(d<player.r+c.r+8){c.dead=true;player.chestsOpened++;openAugmentChoice();break}}}
function updateHazards(dt){for(const h of hazards){if(h.dead)continue;h.age=(h.age||0)+dt;if(!Number.isFinite(h.age)||h.age>GAME_OBJECT_LIMITS.hazardMaxLife){h.dead=true;GamePerf.noteCull("hazards");continue}if(h.type==="blast"){h.time-=dt;if(h.time<=0){if(Math.hypot(player.x-h.x,player.y-h.y)<h.r+player.r)hurtPlayer(h.damage);addVisual({type:"ring",x:h.x,y:h.y,r:h.r,life:.35,max:.35,color:h.color||"#b6323a",width:7});particle(h.x,h.y,h.color||"#b6323a",120,12);h.dead=true}}else if(h.type==="orb"){if(h.homing){const ta=Math.atan2(player.y-h.y,player.x-h.x),ca=Math.atan2(h.vy,h.vx),sp=Math.hypot(h.vx,h.vy)||1,da=Math.atan2(Math.sin(ta-ca),Math.cos(ta-ca));const na=ca+da*Math.min(1,h.homing*dt);h.vx=Math.cos(na)*sp;h.vy=Math.sin(na)*sp}h.x+=h.vx*dt;h.y+=h.vy*dt;h.life-=dt;if(Math.hypot(player.x-h.x,player.y-h.y)<player.r+h.r){hurtPlayer(h.damage);h.dead=true}else if(h.life<=0)h.dead=true}else if(h.type==="puddle"){h.life-=dt;if(!Number.isFinite(h.life)||h.life<=0){h.dead=true;continue}h.tick-=dt;if(h.tick<=0){h.tick=.32;if(Math.hypot(player.x-h.x,player.y-h.y)<h.r+player.r)hurtPlayer(h.damage)}}else if(h.type==="cross"){h.time-=dt;if(h.time<=0){const w=h.w||38;if(Math.abs(player.x-h.x)<w+player.r||Math.abs(player.y-h.y)<w+player.r)hurtPlayer(h.damage);addVisual({type:"line",x1:h.x-900,y1:h.y,x2:h.x+900,y2:h.y,width:w*1.2,life:.18,max:.18,color:h.color||"#df5a63"});addVisual({type:"line",x1:h.x,y1:h.y-900,x2:h.x,y2:h.y+900,width:w*1.2,life:.18,max:.18,color:h.color||"#df5a63"});h.dead=true}}else{h.dead=true;GamePerf.noteCull("hazards")}}}
function updateFields(dt){for(const f of fields){f.age=(f.age||0)+dt;f.life-=dt;if(!Number.isFinite(f.life)||!Number.isFinite(f.age)||f.age>GAME_OBJECT_LIMITS.fieldMaxLife){f.life=0;GamePerf.noteCull("fields");continue}f.tick-=dt;if(f.tick<=0){f.tick=.55;for(const e of GameSpatial.queryCircle(f.x,f.y,f.r+64)){if(e.dead)continue;if(Math.hypot(e.x-f.x,e.y-f.y)<f.r+e.r)damageEnemy(e,f.damage,f.source||"poison",{poison:f.poisonPotency||f.damage*.8,poisonTime:2.5,color:f.color,skipImpactVfx:f.source==="demonMiasma"})}}}}
