function updateParticles(dt){for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.08,dt);p.vy*=Math.pow(.08,dt);p.life-=dt}}
function updateVisuals(dt){for(const v of visuals){v.age=(v.age||0)+dt;v.life-=dt;if(!Number.isFinite(v.life)||!Number.isFinite(v.age)||v.age>GAME_OBJECT_LIMITS.visualMaxLife){v.life=0;GamePerf.noteCull("visuals")}}}
function updateHud(){ui.hpFill.style.width=Math.max(0,player.hp/player.maxHp*100)+"%";ui.xpFill.style.width=Math.max(0,player.xp/player.xpNeed*100)+"%";ui.levelText.textContent="경지 "+player.level;ui.timeText.textContent=difficultyDefs[selectedDifficulty].endless?fmtTime(elapsed):fmtTime(runDuration-elapsed);ui.killText.textContent="격파 "+player.kills;ui.goldHud.textContent=`금자 ${Math.floor(account.gold||0)}`;ui.oreHud.textContent=`광석 ${totalOres()}`;const cd=Math.max(0,player.dodgeCooldown);ui.dodgeHud.textContent=cd>0?`보법 ${cd.toFixed(1)}초`:"보법 준비";ui.dodgeCd.textContent=cd>0?cd.toFixed(1)+"초":"준비";ui.dodgeBtn.classList.toggle("cooling",cd>0);if(boss&&!boss.dead){ui.bossFill.style.width=Math.max(0,boss.hp/boss.maxHp*100)+"%";ui.bossText.textContent=Math.ceil(boss.hp)+" / "+Math.ceil(boss.maxHp)}}
